2514	    /// thread writes only atomically while `'a` lasts: through `thread.h`'s operations, which
2515	    /// are these exports, or through the atomic its handles lend.
2516	    unsafe fn atomic32<'a>(a: *mut sys::git_atomic32) -> Atomic32Ref<'a> {
2517	        // SAFETY: the caller guarantees the object for `'a`. `ref_from_ptr` lets nothing but a
2518	        // `Mut` of the same borrow write it while the handle lives; an `Atomic32Ref` admits
2519	        // beside it the atomic writes its own `val` makes, which is every write the caller
2520	        // lets happen, the one exception `atomic_type!`'s `CCell` impl takes
2521	        // (`crustify/evolution/ffibox-atomic-layout-types`).
2522	        match unsafe { Atomic32Ref::from_ptr(a) } {
2523	            Some(handle) => handle,
2524	            None => process::abort(),
2525	        }
2526	    }
