2720	    /// # Safety
2721	    ///
2722	    /// `key` is valid and aligned for a write of a `pthread_key_t`. `destroy_fn`, if not
2723	    /// `NULL`, may be called once with each value C stores under the key, on the thread that
2724	    /// stored it, at that thread's exit, while the key lives.
2725	    #[unsafe(no_mangle)]
2726	    unsafe extern "C" fn git_tlsdata_init(
2727	        key: *mut sys::pthread_key_t,
2728	        destroy_fn: Option<unsafe extern "C" fn(*mut c_void)>,
2729	    ) -> c_int {
2730	        // SAFETY: the caller vouches for `destroy_fn` with the key it makes, as
2731	        // `CDestructor::new` asks.
2732	        let destructor = destroy_fn.map(|f| unsafe { CDestructor::new(f) });
2733	        match barrier(|| c_keys::init(destructor).ok(), || None) {
2734	            Some(id) => {
2735	                // SAFETY: the caller guarantees that `key` is valid for the write.
2736	                unsafe { key.write(id) };
2737	                0
2738	            }
2739	            None => -1,
2740	        }
2741	    }
