2743	    /// `git_tlsdata_set`: stores `value` as this thread's value of C's key `key`, `NULL`
2744	    /// removing it, and returns 0; returns -1 when `key` names none of C's live keys, or while
2745	    /// the thread exits. The value replaced is left to C, as POSIX leaves it. A panic is
2746	    /// reported as a failure.
2747	    ///
2748	    /// # Safety
2749	    ///
2750	    /// `value`, if not `NULL`, may be passed to `key`'s destructor at this thread's exit.
2751	    #[unsafe(no_mangle)]
2752	    unsafe extern "C" fn git_tlsdata_set(key: sys::pthread_key_t, value: *mut c_void) -> c_int {
2753	        // SAFETY: the caller vouches for `value` with `key`'s destructor, as `CWord::new` asks;
2754	        // the word is stored under `key` alone.
2755	        let word = NonNull::new(value).map(|value| unsafe { CWord::new(value) });
2756	        if barrier(|| c_keys::set(key, word).is_ok(), || false) {
2757	            0
2758	        } else {
2759	            -1
2760	        }
2761	    }
2762	
2763	    /// `git_tlsdata_get`: this thread's value of C's key `key`, `NULL` where it holds none, or
2764	    /// where `key` names none of C's live keys. A panic is reported as `NULL`.
2765	    #[unsafe(no_mangle)]
2766	    extern "C" fn git_tlsdata_get(key: sys::pthread_key_t) -> *mut c_void {
2767	        barrier(
2768	            || c_keys::get(key).map_or(ptr::null_mut(), CWord::as_ptr),
2769	            ptr::null_mut,
2770	        )
2771	    }
2772	
2773	    /// `git_tlsdata_dispose`: disposes of C's key `key`, running no destructor, and returns 0;
2774	    /// returns -1 when `key` names none of C's live keys. A panic is reported as a failure.
2775	    #[unsafe(no_mangle)]
2776	    extern "C" fn git_tlsdata_dispose(key: sys::pthread_key_t) -> c_int {
2777	        if barrier(|| c_keys::dispose(key).is_ok(), || false) {
2778	            0
2779	        } else {
2780	            -1
2781	        }
2782	    }
