3212	        /// value, and leaves the same value, which the other side then reads: two counts run
3213	        /// the sequence, one through each side, and a third alternates between them.
3214	        #[test]
3215	        #[cfg_attr(miri, ignore = "calls C")]
3216	        fn atomic32_exports_match_the_header() {
3217	            let (rust, c, mixed) = (Atomic32::new(0), Atomic32::new(0), Atomic32::new(0));
3218	            let ptr = |v: &Atomic32| v.as_ref().as_ptr().cast_mut();
3219	            for (i, step) in STEPS.into_iter().enumerate() {
3220	                // SAFETY: each pointer addresses a count of this test, live, which only these
3221	                // atomic calls write.
3222	                let from_rust = unsafe { run(true, ptr(&rust), step) };
3223	                // SAFETY: as above.
3224	                let from_c = unsafe { run(false, ptr(&c), step) };
3225	                // SAFETY: as above.
3226	                let from_mixed = unsafe { run(i % 2 == 0, ptr(&mixed), step) };
3227	                assert_eq!(from_rust, from_c, "{step:?}");
3228	                assert_eq!(from_mixed, from_c, "{step:?}");
3229	                assert_eq!(rust.as_ref().get(), c.as_ref().get(), "{step:?}");
3230	                assert_eq!(mixed.as_ref().get(), c.as_ref().get(), "{step:?}");
3231	            }
3232	        }
