3234	        /// The 64-bit exports return what the header's C returns, on one value they share.
3235	        #[cfg(target_pointer_width = "64")]
3236	        #[test]
3237	        #[cfg_attr(miri, ignore = "calls C")]
3238	        fn atomic64_exports_match_the_header() {
3239	            let size = Atomic64::new(0);
3240	            let a = size.as_ref().as_ptr().cast_mut();
3241	            // SAFETY: `a` addresses `size`, live for the test, which only these atomic calls
3242	            // write.
3243	            unsafe { sys::git_atomic64_set(a, i64::MAX - 1) };
3244	            // SAFETY: as above.
