3246	            // SAFETY: as above.
3247	            assert_eq!(unsafe { sys::git_atomic64_add(a, 1) }, i64::MIN);
3248	            // SAFETY: as above.
3249	            let from_rust = unsafe { git_atomic64_get(a) };
3250	            // SAFETY: as above.
3251	            let from_c = unsafe { sys::git_atomic64_get(a) };
3252	            assert_eq!(from_rust, from_c);
3253	            // SAFETY: as above.
3254	            unsafe { git_atomic64_set(a, 12) };
3255	            // SAFETY: as above.
3256	            assert_eq!(unsafe { sys::git_atomic64_get(a) }, 12);
3257	        }
3258	
3259	        /// The slot exports and the header's C on one slot: what one stores the other finds,
3260	        /// a compare-and-swap of either refuses the other's stale value, and both swap out
3261	        /// what the other stored.
3262	        #[test]
3263	        #[cfg_attr(miri, ignore = "calls C")]
3264	        fn slot_exports_match_the_header() {
3265	            let (one, two) = (
3266	                ptr::without_provenance_mut(0x10),
3267	                ptr::without_provenance_mut(0x20),
3268	            );
3269	            let mut slot: *mut c_void = ptr::null_mut();
3270	            let p = &raw mut slot;
3271	            // SAFETY: `p` addresses `slot`, a local live for the test, which only these atomic
3272	            // calls access.
3273	            assert!(unsafe { git_atomic__compare_and_swap(p, ptr::null_mut(), one) }.is_null());
3274	            // SAFETY: as above.
3275	            let found = unsafe { sys::git_atomic__compare_and_swap(p, ptr::null_mut(), two) };
3276	            assert_eq!(found, one, "C refuses the export's stale value");
3277	            // SAFETY: as above.
3278	            let found = unsafe { sys::git_atomic__compare_and_swap(p, one, two) };
3279	            assert_eq!(found, one);
3280	            // SAFETY: as above.
3281	            let found = unsafe { git_atomic__compare_and_swap(p, one, ptr::null_mut()) };
3282	            assert_eq!(found, two, "the export refuses C's stale value");
3283	            // SAFETY: as above.
3284	            let from_rust = unsafe { git_atomic__load(p) };
3285	            // SAFETY: as above.
3286	            let from_c = unsafe { sys::git_atomic__load(p) };
3287	            assert_eq!(from_rust, from_c);
3288	            // SAFETY: as above.
3289	            assert_eq!(unsafe { git_atomic__swap(p, one) }, two);
3290	            // SAFETY: as above.
3291	            assert_eq!(unsafe { sys::git_atomic__swap(p, ptr::null_mut()) }, one);
3292	            // SAFETY: as above.
3293	            assert!(unsafe { git_atomic__load(p) }.is_null());
3294	        }
3295	
3296	        /// C threads and export threads raise and drop one reference count at once and lose
3297	        /// no update, as `GIT_REFCOUNT_INC` and `GIT_REFCOUNT_DEC` will once the C that
3298	        /// remains reaches the exports while the header's bodies are still expanded elsewhere.
3299	        #[test]
3300	        #[cfg_attr(miri, ignore = "calls C")]
