905	///
906	/// The closure owns what it captures (`'static`), where C hands its thread a pointer
907	/// that the caller keeps alive until the join; a thread that borrows its caller's data
908	/// is started in a [`std::thread::scope`]. A thread nothing joins runs on after its
909	/// handle is dropped, detached, where C's runs on unjoined.
910	///
911	/// # Errors
912	///
913	/// The system's error when it cannot start a thread, as `pthread_create` reports it
914	/// (`EAGAIN` when a resource limit is reached), which libgit2 reports as
915	/// `GIT_ERROR_THREAD`.
916	///
917	/// Replaces `mac::git_thread_create`
918	#[doc(alias = "git_thread_create")]
919	pub fn spawn<F, T>(f: F) -> io::Result<JoinHandle<T>>
920	where
921	    F: FnOnce() -> T + Send + 'static,
922	    T: Send + 'static,
923	{
924	    std::thread::Builder::new()
925	        .spawn(f)
