929	/// A thread [`spawn`] started, which [`join`](Self::join) waits for and whose result
930	/// it returns.
931	pub struct JoinHandle<T> {
932	    inner: std::thread::JoinHandle<T>,
933	}
934	
935	impl<T> JoinHandle<T> {
936	    /// Waits for the thread to end and returns what its closure returned, as
937	    /// `git_thread_join` waits and reads the start routine's result through `status`.
938	    /// The handle is consumed, so the thread is joined once.
939	    ///
940	    /// # Errors
941	    ///
942	    /// When the closure panicked, the panic's payload, which
943	    /// [`std::panic::resume_unwind`] can propagate; C's thread has no such ending.
944	    ///
945	    /// # Panics
946	    ///
947	    /// When the thread joins itself, through a handle it was given: `pthread_join`
948	    /// refuses that with `EDEADLK`.
949	    ///
950	    /// Replaces `mac::git_thread_join`
951	    #[doc(alias = "git_thread_join")]
952	    pub fn join(self) -> std::thread::Result<T> {
953	        self.inner.join()
954	    }
955	
956	    /// The thread, as the standard library names it.
957	    #[must_use]
958	    pub fn thread(&self) -> &std::thread::Thread {
959	        self.inner.thread()
960	    }
961	
962	    /// Whether the thread's closure has returned or panicked, so that
963	    /// [`join`](Self::join) would not block.
964	    #[must_use]
965	    pub fn is_finished(&self) -> bool {
966	        self.inner.is_finished()
967	    }
968	}
969	
970	impl<T> fmt::Debug for JoinHandle<T> {
