1003	    /// value Rust holds may only be read through; the value here is written through shared
1004	    /// access, so the layout type is written by hand against [`CCell`]'s contract, over an
1005	    /// `UnsafeCell` of the C struct.
1006	    macro_rules! atomic_type {
1007	        (
1008	            $(#[$attr:meta])*
1009	            $name:ident, $rf:ident, $mt:ident, $c_name:ident, $atomic:ty, $int:ty,
1010	            val: $(#[$val_attr:meta])*
