1021	            #[derive(Clone, Copy)]
1022	            pub struct $rf<'a>(CBorrowedPtr<'a, $name>);
1023	
1024	            #[doc = concat!(
1025	                "Exclusive borrow of an [`", stringify!($name), "`]. ",
1026	                "Reaches the value through [`as_ref`](Self::as_ref)."
1027	            )]
1028	            #[repr(transparent)]
1029	            pub struct $mt<'a>(
1030	                $rf<'a>,
1031	                // Invariant in the pointee, as `&'a mut` is; see `CCell`'s contract.
1032	                PhantomData<&'a mut $name>,
1033	            );
