        /// Wraps `fld::git_thread.thread`
        #[doc(alias = "git_thread.thread")]
        #[must_use]
        pub fn thread(&self) -> RawPthread {
            // SAFETY: `self.as_ptr()` addresses the live object this handle borrows; the
            // projection forms no reference to it.
