            let mut registry = Registry::new();
            let rust = registry.create(plain()).expect("an id").get();
            let c = registry.create(Destructor::C(None)).expect("an id").get();
            assert!(registry.holds(rust, Kind::Rust(TypeId::of::<()>())));
