// ---------------------------------------------------------------------------------------------
// Atomic operations (`thread.h`): `git_atomic32_*`, `git_atomic64_*`, `git_atomic_ssize_*`,
// the pointer-sized `git_atomic_*` and `GIT_MEMORY_BARRIER`.
