#[test]
fn atomic_ssize_adds_and_reads_back() {
    static STORAGE: AtomicSsize = AtomicSsize::new(0);
    let storage = STORAGE.as_ref();
    let max = i64::try_from(isize::MAX).unwrap();
    assert_eq!(storage.add(max), max);
