    let slot = AtomicIsize::new(-7);
    assert_eq!(atomic_compare_and_swap(&slot, -7, -7), -7);
    assert_eq!(atomic_load(&slot), -7);
    assert_eq!(atomic_compare_and_swap(&slot, isize::MIN, isize::MAX), -7);
    assert_eq!(atomic_load(&slot), -7);
}

